#!/usr/bin/env python3
"""Build /results/recovered.json from the live Redis instance on 127.0.0.1:6379."""
import json
import socket

HOST, PORT = "127.0.0.1", 6379


class Resp:
    def __init__(self, host, port):
        self.sock = socket.create_connection((host, port))
        self.buf = b""

    def _line(self):
        while b"\r\n" not in self.buf:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise EOFError("connection closed")
            self.buf += chunk
        line, self.buf = self.buf.split(b"\r\n", 1)
        return line

    def _exact(self, n):
        while len(self.buf) < n + 2:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise EOFError("connection closed")
            self.buf += chunk
        data, self.buf = self.buf[:n], self.buf[n + 2:]
        return data

    def _read(self):
        line = self._line()
        tag, rest = line[:1], line[1:]
        if tag == b"+":
            return rest.decode()
        if tag == b"-":
            raise RuntimeError(rest.decode())
        if tag == b":":
            return int(rest)
        if tag == b"$":
            n = int(rest)
            return None if n == -1 else self._exact(n).decode()
        if tag == b"*":
            n = int(rest)
            return None if n == -1 else [self._read() for _ in range(n)]
        raise RuntimeError("unexpected RESP tag: %r" % line)

    def cmd(self, *args):
        out = [b"*%d\r\n" % len(args)]
        for a in args:
            b = a.encode() if isinstance(a, str) else a
            out.append(b"$%d\r\n%s\r\n" % (len(b), b))
        self.sock.sendall(b"".join(out))
        return self._read()


def num(s):
    """Render a Redis score as a JSON number, preferring int when integral."""
    f = float(s)
    return int(f) if f.is_integer() else f


def main():
    r = Resp(HOST, PORT)
    assert r.cmd("PING") == "PONG"

    # Determine which logical DB holds the data (0 unless the AOF selected another).
    db = 0
    for line in r.cmd("INFO", "keyspace").splitlines():
        if line.startswith("db") and ":keys=" in line:
            idx = int(line[2:line.index(":")])
            if int(line.split(":keys=")[1].split(",")[0]) > 0:
                db = idx
                break
    if db != 0:
        r.cmd("SELECT", str(db))

    # Full keyspace via a complete SCAN cursor walk.
    names, cursor = [], "0"
    while True:
        cursor, batch = r.cmd("SCAN", cursor, "COUNT", "1000")
        names.extend(batch)
        if cursor == "0":
            break
    names = sorted(set(names))

    keys = []
    for name in names:
        t = r.cmd("TYPE", name)
        if t == "string":
            value = r.cmd("GET", name)
        elif t == "hash":
            flat = r.cmd("HGETALL", name)
            pairs = dict(zip(flat[0::2], flat[1::2]))
            value = {k: pairs[k] for k in sorted(pairs)}
        elif t == "list":
            value = r.cmd("LRANGE", name, "0", "-1")
        elif t == "set":
            value = sorted(r.cmd("SMEMBERS", name))
        elif t == "zset":
            flat = r.cmd("ZRANGE", name, "0", "-1", "WITHSCORES")
            items = [{"member": m, "score": num(s)}
                     for m, s in zip(flat[0::2], flat[1::2])]
            value = sorted(items, key=lambda d: d["member"])
        elif t == "stream":
            value = []
            for entry_id, flat in r.cmd("XRANGE", name, "-", "+"):
                value.append({
                    "id": entry_id,
                    "fields": dict(zip(flat[0::2], flat[1::2])),
                })
        else:
            raise RuntimeError("unhandled type %r for key %r" % (t, name))
        keys.append({"name": name, "type": t, "value": value})

    doc = {"db": db, "keys": keys}
    with open("/results/recovered.json", "w", encoding="utf-8") as fh:
        json.dump(doc, fh, ensure_ascii=False, indent=2)
        fh.write("\n")
    print("wrote /results/recovered.json: db=%d keys=%d" % (db, len(keys)))


if __name__ == "__main__":
    main()

